public class Main {
  static int modify(int[] arr, int idx) {
    arr[idx] = arr[idx] * 2;
    return arr[idx] + idx;
  }

  public static void main(String[] args) {
    int[] numbers = {1, 2, 3, 4, 5};
    int sum = 0;

    for (int i = 0; i < numbers.length; i++) {
      if (i % 2 == 0) {
        sum += modify(numbers, i);
      } else {
        sum += numbers[i];
      }
    }

    System.out.println("sum = " + sum);

    for (int n : numbers) {
      System.out.print(n + " ");
    }
  }
}

#include <stdio.h>

void update(int *p, int n) {
  for (int i = 0; i < n; i++) {
    if (i % 2 == 0) {
      *(p + i) += 10;
    } else {
      *(p + i) -= 5;
    }
  }
}

int main() {
  int arr[5] = {1, 2, 3, 4, 5};
  int total = 0;

  update(arr, 5);

  for (int i = 0; i < 5; i++) {
    total += arr[i];
    printf("%d ", arr[i]);
  }

  printf("\ntotal = %d\n", total);

  return 0;
}

